import { generateText, streamText, } from 'ai';
const systemPrompt = 'You are a sophisticated web scraper. Extract the contents of the webpage';
const systemCodePrompt = "Provide a scraping function in JavaScript that extracts and returns data according to a schema from the current page. The function must be IIFE. No comments or imports. No console.log. The code you generate will be executed straight away, you shouldn't output anything besides runnable code.";
function stripMarkdownBackticks(text) {
    let trimmed = text.trim();
    trimmed = trimmed.replace(/^```(?:javascript)?\s*/i, '');
    trimmed = trimmed.replace(/\s*```$/i, '');
    return trimmed;
}
function prepareAISDKPage(page) {
    if (page.format === 'image') {
        return [
            {
                type: 'image',
                image: page.content,
            },
        ];
    }
    return [{ type: 'text', text: page.content }];
}
export async function generateAISDKCompletions(model, page, output, options) {
    const pageContent = prepareAISDKPage(page);
    const { system = systemPrompt, messages: messagesOptions, ...rest } = options || {};
    const messages = [
        { role: 'user', content: pageContent },
        ...(messagesOptions || []),
    ];
    const result = await generateText({
        model,
        output,
        system,
        messages,
        ...rest,
    });
    return {
        data: result.output,
        url: page.url,
    };
}
export function streamAISDKCompletions(model, page, output, options) {
    const pageContent = prepareAISDKPage(page);
    const { system = systemPrompt, messages: messagesOptions, ...rest } = options || {};
    const messages = [
        { role: 'user', content: pageContent },
        ...(messagesOptions || []),
    ];
    const { partialOutputStream } = streamText({
        model,
        output,
        system,
        messages,
        ...rest,
    });
    return {
        stream: partialOutputStream,
        url: page.url,
    };
}
export async function generateAISDKCode(model, page, output, options) {
    const responseFormat = await output.responseFormat;
    // Extract JSON Schema from responseFormat (AI SDK already converts Zod schemas to JSON Schema)
    const jsonSchema = responseFormat.type === 'json' && 'schema' in responseFormat
        ? responseFormat.schema
        : output;
    const { system = systemCodePrompt, messages: messagesOptions, ...rest } = options || {};
    const messages = [
        {
            role: 'user',
            content: `Website: ${page.url}
      Schema: ${JSON.stringify(jsonSchema)}
      Content: ${page.content}`,
        },
        ...(messagesOptions || []),
    ];
    const result = await generateText({
        model,
        system,
        messages,
        ...rest,
    });
    return {
        code: stripMarkdownBackticks(result.text),
        url: page.url,
    };
}
